const body = $json.body ?? $json;

const cliente = String(body.cliente ?? 'Cliente').trim() || 'Cliente';
const canalRaw = String(body.canal ?? 'whatsapp').toLowerCase().trim();
const canal = canalRaw.includes('insta') ? 'instagram' : 'whatsapp';
const mensagem = String(body.mensagem ?? '').trim();

const telefone = String(body.telefone ?? '').trim();
const email = String(body.email ?? '').trim();

const fallbackCliente = cliente
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '') || 'cliente';

const firstNonEmpty = (...values) => {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
};

const clienteKey = firstNonEmpty(
  body.cliente_id,
  body.identificador_externo,
  telefone,
  email,
  `${canal}:${fallbackCliente}`
);

const conversaKey = firstNonEmpty(
  body.conversa_id,
  body.chat_id,
  `${canal}:${clienteKey}`
);

let horario;
try {
  horario = body.horario ? new Date(body.horario).toISOString() : new Date().toISOString();
} catch {
  horario = new Date().toISOString();
}

return [{
  json: {
    cliente,
    canal,
    mensagem,
    telefone,
    email,
    clienteKey,
    conversaKey,
    horario
  }
}];
